//! Version-aware `pumpkin.toml` profiles and validation core.
//!
//! Phase 4, Task 1. Ground truth for the guided-field list is the live
//! `pumpkin.toml` generated by `ghcr.io/pumpkin-mc/pumpkin:master`
//! (Pumpkin 0.2.0+26.3-26.51, dumped 2026-10-15):
//! top-level `seed`, `default_difficulty`, `default_gamemode`,
//! `default_level_name`, `hardcore`, `white_list`, `enforce_whitelist`, `tps`,
//! plus `motd`, `max_players`, `view_distance`, `simulation_distance`,
//! `online_mode` under `[networking.java]` and `[networking.bedrock]`.
//!
//! Validation deliberately rejects nothing unknown: any key outside the guided
//! set (including whole custom sections) is preserved untouched. Only TOML
//! syntax errors, guided-field type mismatches, and numeric range violations
//! are reported.

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use toml_edit::{DocumentMut, Entry, Item, Table, Value};

/// Hard bounds for numeric guided fields. Best-effort typo guards only:
/// unknown keys are never rejected and Pumpkin itself remains the final
/// arbiter at boot.
const TPS_MIN_EXCLUSIVE: f64 = 0.0;
const TPS_MAX: f64 = 1000.0;
const MAX_PLAYERS_MIN: i64 = 1;
const MAX_PLAYERS_MAX: i64 = 100_000;
const DISTANCE_MIN: i64 = 1;
const DISTANCE_MAX: i64 = 128;

/// Version profile for a Pumpkin server release.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PumpkinProfile {
    /// Raw version string (e.g. from `servers.runtime_version`).
    pub pumpkin_version: String,
    /// True when the version's config schema is known (`26.x`).
    pub known: bool,
}

/// Profile for a Pumpkin version string. `known=true` for `26.x`;
/// everything else yields `known=false` (Task 2 surfaces a warning banner).
pub fn profile_for_version(version: &str) -> PumpkinProfile {
    let stripped = version.trim().trim_start_matches(['v', 'V']);
    let known = stripped
        .split(['.', '-', '+'])
        .next()
        .is_some_and(|major| major == "26");
    PumpkinProfile {
        pumpkin_version: version.to_string(),
        known,
    }
}

/// Guided (form-editable) subset of `pumpkin.toml`. Every key verified present
/// in the live dumped TOML. `None` means "leave untouched".
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
pub struct GuidedConfig {
    pub seed: Option<String>,
    pub default_difficulty: Option<String>,
    pub default_gamemode: Option<String>,
    pub default_level_name: Option<String>,
    pub hardcore: Option<bool>,
    pub white_list: Option<bool>,
    pub enforce_whitelist: Option<bool>,
    pub tps: Option<f64>,
    pub motd: Option<String>,
    pub max_players: Option<i64>,
    pub view_distance: Option<i64>,
    pub simulation_distance: Option<i64>,
    pub online_mode: Option<bool>,
}

/// Parse TOML and range-check guided fields. `Ok` keeps full formatting;
/// `Err` is a non-empty list of human-readable messages. Unknown keys and
/// sections are never errors.
pub fn parse_and_validate(content: &str) -> Result<DocumentMut, Vec<String>> {
    let doc = content
        .parse::<DocumentMut>()
        .map_err(|e| vec![format!("invalid TOML syntax: {e}")])?;
    let mut errors: Vec<String> = Vec::new();

    check_opt_string(&doc, None, "seed", &mut errors);
    check_opt_string(&doc, None, "default_difficulty", &mut errors);
    check_opt_string(&doc, None, "default_gamemode", &mut errors);
    check_opt_string(&doc, None, "default_level_name", &mut errors);
    check_opt_bool(&doc, None, "hardcore", &mut errors);
    check_opt_bool(&doc, None, "white_list", &mut errors);
    check_opt_bool(&doc, None, "enforce_whitelist", &mut errors);
    if let Some(item) = top_item(&doc, "tps") {
        match number(item) {
            None => errors.push("tps must be a number (ticks per second)".to_string()),
            Some(v) => {
                if !(v.is_finite() && v > TPS_MIN_EXCLUSIVE && v <= TPS_MAX) {
                    errors.push(format!(
                        "tps must be greater than {TPS_MIN_EXCLUSIVE} and at most {TPS_MAX} (got {v})"
                    ));
                }
            }
        }
    }
    for side in ["java", "bedrock"] {
        let ctx = format!("networking.{side}");
        check_opt_string(&doc, Some(&ctx), "motd", &mut errors);
        check_opt_bool(&doc, Some(&ctx), "online_mode", &mut errors);
        check_opt_int_range(
            &doc,
            Some(&ctx),
            "max_players",
            MAX_PLAYERS_MIN,
            MAX_PLAYERS_MAX,
            &mut errors,
        );
        check_opt_int_range(
            &doc,
            Some(&ctx),
            "view_distance",
            DISTANCE_MIN,
            DISTANCE_MAX,
            &mut errors,
        );
        check_opt_int_range(
            &doc,
            Some(&ctx),
            "simulation_distance",
            DISTANCE_MIN,
            DISTANCE_MAX,
            &mut errors,
        );
    }

    if errors.is_empty() {
        Ok(doc)
    } else {
        Err(errors)
    }
}

/// Apply `Some` guided fields onto `doc`, preserving everything else
/// byte-for-byte (unknown keys, sections, comments, ordering).
/// Nested fields (`motd`, `max_players`, `view_distance`,
/// `simulation_distance`, `online_mode`) are written to both
/// `[networking.java]` and `[networking.bedrock]` to keep editions in sync.
pub fn apply_guided(doc: &mut DocumentMut, guided: &GuidedConfig) {
    if let Some(v) = guided.seed.as_deref() {
        set_top(doc, "seed", v.into());
    }
    if let Some(v) = guided.default_difficulty.as_deref() {
        set_top(doc, "default_difficulty", v.into());
    }
    if let Some(v) = guided.default_gamemode.as_deref() {
        set_top(doc, "default_gamemode", v.into());
    }
    if let Some(v) = guided.default_level_name.as_deref() {
        set_top(doc, "default_level_name", v.into());
    }
    if let Some(v) = guided.hardcore {
        set_top(doc, "hardcore", v.into());
    }
    if let Some(v) = guided.white_list {
        set_top(doc, "white_list", v.into());
    }
    if let Some(v) = guided.enforce_whitelist {
        set_top(doc, "enforce_whitelist", v.into());
    }
    if let Some(v) = guided.tps {
        set_top(doc, "tps", v.into());
    }
    if let Some(v) = guided.motd.as_deref() {
        set_nested(doc, "motd", v.into());
    }
    if let Some(v) = guided.max_players {
        set_nested(doc, "max_players", v.into());
    }
    if let Some(v) = guided.view_distance {
        set_nested(doc, "view_distance", v.into());
    }
    if let Some(v) = guided.simulation_distance {
        set_nested(doc, "simulation_distance", v.into());
    }
    if let Some(v) = guided.online_mode {
        set_nested(doc, "online_mode", v.into());
    }
}

/// Read the guided subset back out of a parsed document. Nested fields prefer
/// `[networking.java]`, falling back to `[networking.bedrock]`.
pub fn guided_from_doc(doc: &DocumentMut) -> GuidedConfig {
    GuidedConfig {
        seed: read_string(doc, None, "seed"),
        default_difficulty: read_string(doc, None, "default_difficulty"),
        default_gamemode: read_string(doc, None, "default_gamemode"),
        default_level_name: read_string(doc, None, "default_level_name"),
        hardcore: read_bool(doc, None, "hardcore"),
        white_list: read_bool(doc, None, "white_list"),
        enforce_whitelist: read_bool(doc, None, "enforce_whitelist"),
        tps: top_item(doc, "tps").and_then(number),
        motd: read_nested_string(doc, "motd"),
        max_players: read_nested_int(doc, "max_players"),
        view_distance: read_nested_int(doc, "view_distance"),
        simulation_distance: read_nested_int(doc, "simulation_distance"),
        online_mode: read_nested_bool(doc, "online_mode"),
    }
}

/// SHA-256 hex digest of config content (revision tracking / ETags).
pub fn content_hash(content: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(content.as_bytes());
    format!("{:x}", hasher.finalize())
}

// --- internal helpers ---

/// Top-level item lookup.
fn top_item<'a>(doc: &'a DocumentMut, key: &str) -> Option<&'a Item> {
    doc.get(key)
}

/// Item lookup inside `[networking.<side>]`; `None` when any level is absent.
fn nested_item<'a>(doc: &'a DocumentMut, side: &str, key: &str) -> Option<&'a Item> {
    doc.get("networking")?
        .as_table_like()?
        .get(side)?
        .as_table_like()?
        .get(key)
}

/// Nested read with `java` preferred, `bedrock` as fallback.
fn nested_fallback<'a>(doc: &'a DocumentMut, key: &str) -> Option<&'a Item> {
    nested_item(doc, "java", key).or_else(|| nested_item(doc, "bedrock", key))
}

/// Numeric value of an item, accepting integers for float fields (TOML has no
/// implicit int->float coercion, but we stay lenient: Pumpkin is the final
/// arbiter at boot).
fn number(item: &Item) -> Option<f64> {
    match item.as_value()? {
        Value::Float(f) => Some(*f.value()),
        Value::Integer(i) => Some(*i.value() as f64),
        _ => None,
    }
}

/// Integer value, accepting integral floats.
fn integer(item: &Item) -> Option<i64> {
    match item.as_value()? {
        Value::Integer(i) => Some(*i.value()),
        Value::Float(f) if f.value().fract() == 0.0 => Some(*f.value() as i64),
        _ => None,
    }
}

fn display_path(section: Option<&str>, key: &str) -> String {
    match section {
        None => key.to_string(),
        Some(s) => format!("{s}.{key}"),
    }
}

fn section_item<'a>(doc: &'a DocumentMut, section: Option<&str>, key: &str) -> Option<&'a Item> {
    match section {
        None => top_item(doc, key),
        Some(s) => s
            .strip_prefix("networking.")
            .and_then(|side| nested_item(doc, side, key)),
    }
}

fn check_opt_string(doc: &DocumentMut, section: Option<&str>, key: &str, errors: &mut Vec<String>) {
    if let Some(item) = section_item(doc, section, key) {
        if item.as_str().is_none() {
            errors.push(format!("{} must be a string", display_path(section, key)));
        }
    }
}

fn check_opt_bool(doc: &DocumentMut, section: Option<&str>, key: &str, errors: &mut Vec<String>) {
    if let Some(item) = section_item(doc, section, key) {
        if item.as_bool().is_none() {
            errors.push(format!(
                "{} must be a boolean (true/false)",
                display_path(section, key)
            ));
        }
    }
}

fn check_opt_int_range(
    doc: &DocumentMut,
    section: Option<&str>,
    key: &str,
    min: i64,
    max: i64,
    errors: &mut Vec<String>,
) {
    if let Some(item) = section_item(doc, section, key) {
        match integer(item) {
            None => errors.push(format!("{} must be an integer", display_path(section, key))),
            Some(v) => {
                if v < min || v > max {
                    errors.push(format!(
                        "{} must be between {min} and {max} (got {v})",
                        display_path(section, key)
                    ));
                }
            }
        }
    }
}

fn read_string(doc: &DocumentMut, section: Option<&str>, key: &str) -> Option<String> {
    section_item(doc, section, key)?
        .as_str()
        .map(str::to_string)
}

fn read_bool(doc: &DocumentMut, section: Option<&str>, key: &str) -> Option<bool> {
    section_item(doc, section, key)?.as_bool()
}

fn read_nested_string(doc: &DocumentMut, key: &str) -> Option<String> {
    nested_fallback(doc, key)?.as_str().map(str::to_string)
}

fn read_nested_bool(doc: &DocumentMut, key: &str) -> Option<bool> {
    nested_fallback(doc, key)?.as_bool()
}

fn read_nested_int(doc: &DocumentMut, key: &str) -> Option<i64> {
    nested_fallback(doc, key).and_then(integer)
}

/// Set a top-level key, replacing the value in place when the key already
/// exists so comments/ordering/formatting are untouched.
fn set_top(doc: &mut DocumentMut, key: &str, value: Value) {
    match doc.as_table_mut().entry(key) {
        Entry::Occupied(mut e) => {
            e.insert(Item::Value(value));
        }
        Entry::Vacant(e) => {
            e.insert(Item::Value(value));
        }
    }
}

/// Mutable access to `[networking.<side>]`, creating explicit tables when
/// absent. A non-table occupant at any level is replaced (defensive; a
/// `networking = "x"` config could never boot Pumpkin anyway).
fn nested_side_table<'a>(doc: &'a mut DocumentMut, side: &str) -> &'a mut Table {
    let networking = doc
        .as_table_mut()
        .entry("networking")
        .or_insert(Item::Table(Table::new()));
    if !networking.is_table() {
        *networking = Item::Table(Table::new());
    }
    let table = networking.as_table_mut().expect("just ensured a table");
    let side_item = table.entry(side).or_insert(Item::Table(Table::new()));
    if !side_item.is_table() {
        *side_item = Item::Table(Table::new());
    }
    side_item.as_table_mut().expect("just ensured a table")
}

/// Set a nested guided key in both java and bedrock tables.
fn set_nested(doc: &mut DocumentMut, key: &str, value: Value) {
    for side in ["java", "bedrock"] {
        nested_side_table(doc, side).insert(key, Item::Value(value.clone()));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const BASE: &str = r#"seed = "123"
tps = 20.0
# a comment guarding the unknown section
[custom_section]
mystery = "keep me"
"#;

    #[test]
    fn guided_round_trip_preserves_unknown_keys() {
        let mut doc = parse_and_validate(BASE).expect("base must validate");
        apply_guided(
            &mut doc,
            &GuidedConfig {
                seed: Some("999".to_string()),
                max_players: Some(42),
                motd: Some("Hi".to_string()),
                ..Default::default()
            },
        );
        let back = guided_from_doc(&doc);
        assert_eq!(back.seed.as_deref(), Some("999"));
        assert_eq!(back.max_players, Some(42));
        assert_eq!(back.motd.as_deref(), Some("Hi"));
        // Unknown section + key + comment survive byte-for-byte.
        let out = doc.to_string();
        assert!(out.contains("[custom_section]"), "section lost:\n{out}");
        assert!(out.contains("mystery"), "unknown key lost:\n{out}");
        assert!(
            out.contains("# a comment guarding the unknown section"),
            "comment lost:\n{out}"
        );
        // Untouched guided fields keep their values.
        assert_eq!(guided_from_doc(&doc).tps, Some(20.0));
        // Output still validates.
        parse_and_validate(&out).expect("round-tripped doc must validate");
    }

    #[test]
    fn invalid_toml_reports_errors() {
        let errs = parse_and_validate("tps = [unclosed\n:::\n").unwrap_err();
        assert!(!errs.is_empty(), "garbage must produce errors");
    }

    #[test]
    fn range_checks_fire() {
        let content = "tps = -1.0\n[networking.java]\nmax_players = -5\n";
        let errs = parse_and_validate(content).unwrap_err();
        assert!(
            errs.iter().any(|e| e.contains("tps")),
            "tps error missing: {errs:?}"
        );
        assert!(
            errs.iter().any(|e| e.contains("max_players")),
            "max_players error missing: {errs:?}"
        );
    }

    #[test]
    fn unknown_version_profile_is_unknown() {
        let p = profile_for_version("99.9");
        assert!(!p.known);
        assert_eq!(p.pumpkin_version, "99.9");
    }

    #[test]
    fn known_version_profile() {
        for v in ["26", "26.3", "26.51", "v26.1"] {
            let p = profile_for_version(v);
            assert!(p.known, "{v} should be known");
            assert_eq!(p.pumpkin_version, v);
        }
        assert!(parse_and_validate("").is_ok(), "empty doc must parse");
        assert_eq!(
            content_hash("hello"),
            "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824"
        );
    }
}
